package com.rawatibi.lite;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
    private final int NAVY=Color.rgb(17,40,76);
    private JSONObject data;
    private LinearLayout root,body;
    private static final int EXPORT=10, IMPORT=11;
    @Override public void onCreate(Bundle b){super.onCreate(b); load(); unlock();}
    void load(){try{data=new JSONObject(getPreferences(0).getString("data","{\"employees\":[]}"));}catch(Exception e){data=new JSONObject();try{data.put("employees",new JSONArray());}catch(Exception ignored){}}}
    void save(){getPreferences(0).edit().putString("data",data.toString()).apply();}
    JSONArray employees(){JSONArray a=data.optJSONArray("employees");if(a==null){a=new JSONArray();try{data.put("employees",a);}catch(Exception ignored){}}return a;}
    void unlock(){if(android.os.Build.VERSION.SDK_INT>=28){android.hardware.biometrics.BiometricManager m=(android.hardware.biometrics.BiometricManager)getSystemService(BIOMETRIC_SERVICE);if(m!=null && m.canAuthenticate()==android.hardware.biometrics.BiometricManager.BIOMETRIC_SUCCESS){new android.hardware.biometrics.BiometricPrompt.Builder(this).setTitle("Rawatibi Lite").setSubtitle("Unlock with fingerprint").setNegativeButton("Use without fingerprint",getMainExecutor(),(d,w)->home()).build().authenticate(new android.os.CancellationSignal(),getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult r){home();}@Override public void onAuthenticationError(int code,CharSequence msg){home();}});return;}}home();}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(NAVY);t.setPadding(10,12,10,12);return t;}
    Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
    void page(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.WHITE);setContentView(root);TextView h=text(title,23);h.setTextColor(Color.WHITE);h.setBackgroundColor(NAVY);h.setPadding(24,28,24,28);root.addView(h);ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);body.setPadding(20,12,20,20);sc.addView(body);}
    double amount(JSONObject o,String key){return o.optDouble(key,0);}
    double balance(JSONObject e){double n=amount(e,"opening");JSONArray tx=e.optJSONArray("transactions");if(tx!=null)for(int j=0;j<tx.length();j++){JSONObject t=tx.optJSONObject(j);if(t!=null)n+=amount(t,"value")*("salary".equals(t.optString("type"))?1:-1);}return n;}
    String kwd(double v){return String.format(Locale.US,"%.3f KWD",v);}
    void home(){page("Rawatibi Lite");JSONArray es=employees();double total=0;for(int i=0;i<es.length();i++){JSONObject e=es.optJSONObject(i);if(e!=null)total+=balance(e);}body.addView(text("Total outstanding: "+kwd(total),20));body.addView(text("Employees: "+es.length()+" / 8",16));for(int i=0;i<es.length();i++){final int ix=i;JSONObject e=es.optJSONObject(i);if(e!=null)body.addView(button(e.optString("name")+"  •  "+kwd(balance(e)),()->employee(ix)));}if(es.length()<8)body.addView(button("+ Add employee",()->addEmployee()));body.addView(button("Export local backup",()->{Intent in=new Intent(Intent.ACTION_CREATE_DOCUMENT);in.setType("application/json");in.addCategory(Intent.CATEGORY_OPENABLE);in.putExtra(Intent.EXTRA_TITLE,"rawatibi-backup.json");startActivityForResult(in,EXPORT);}));body.addView(button("Import local backup",()->{Intent in=new Intent(Intent.ACTION_OPEN_DOCUMENT);in.setType("application/json");in.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(in,IMPORT);}));}
    EditText field(String hint,String value,boolean numeric){EditText e=new EditText(this);e.setHint(hint);e.setText(value);if(numeric)e.setInputType(8194);body.addView(e);return e;}
    double parse(String s){try{return Double.parseDouble(s.trim());}catch(Exception e){return Double.NaN;}}
    void error(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("OK",null).show();}
    void addEmployee(){page("Add employee");EditText name=field("Employee name","",false),civil=field("Civil ID","",false),salary=field("Monthly salary KWD","",true),opening=field("Previous arrears KWD","0",true);body.addView(button("Save employee",()->{double s=parse(salary.getText().toString()),o=parse(opening.getText().toString());if(name.getText().toString().trim().isEmpty()||civil.getText().toString().trim().isEmpty()||!Double.isFinite(s)||!Double.isFinite(o)||s<0||o<0){error("Enter valid employee details and non-negative amounts.");return;}try{JSONObject e=new JSONObject();e.put("name",name.getText().toString().trim());e.put("civil",civil.getText().toString().trim());e.put("salary",s);e.put("opening",o);e.put("transactions",new JSONArray());employees().put(e);save();home();}catch(Exception ex){error(ex.getMessage());}}));body.addView(button("Cancel",()->home()));}
    void employee(int index){JSONObject e=employees().optJSONObject(index);if(e==null){home();return;}page(e.optString("name"));body.addView(text("Civil ID: "+e.optString("civil"),16));body.addView(text("Monthly salary: "+kwd(amount(e,"salary")),16));body.addView(text("Outstanding: "+kwd(balance(e)),22));body.addView(button("+ Add monthly salary",()->confirmSalary(index)));body.addView(button("Record payment",()->payment(index)));body.addView(text("Transactions (newest first)",18));JSONArray a=e.optJSONArray("transactions");if(a!=null)for(int j=a.length()-1;j>=0;j--){JSONObject t=a.optJSONObject(j);if(t!=null)body.addView(text(t.optString("date")+"  |  "+t.optString("type")+"  |  "+kwd(amount(t,"value"))+"  "+t.optString("method"),14));}body.addView(button("Back",()->home()));}
    void confirmSalary(int index){JSONObject e=employees().optJSONObject(index);new AlertDialog.Builder(this).setTitle("Add monthly salary?").setMessage("Add "+kwd(amount(e,"salary"))+" to outstanding balance. This action is manual.").setNegativeButton("Cancel",null).setPositiveButton("Add",(d,w)->transaction(index,"salary",amount(e,"salary"),"" )).show();}
    void payment(int index){page("Record payment");EditText value=field("Payment amount KWD","",true);final String[] method={"Cash"};RadioGroup rg=new RadioGroup(this);RadioButton cash=new RadioButton(this),bank=new RadioButton(this);cash.setText("Cash");bank.setText("Bank");rg.addView(cash);rg.addView(bank);cash.setChecked(true);rg.setOnCheckedChangeListener((g,id)->method[0]=bank.isChecked()?"Bank":"Cash");body.addView(rg);body.addView(button("Save payment",()->{double v=parse(value.getText().toString());if(!Double.isFinite(v)||v<=0){error("Enter a positive amount.");return;}new AlertDialog.Builder(this).setTitle("Confirm payment").setMessage(kwd(v)+" via "+method[0]).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->transaction(index,"payment",v,method[0])).show();}));body.addView(button("Cancel",()->employee(index)));}
    void transaction(int index,String type,double value,String method){try{JSONObject e=employees().getJSONObject(index);JSONObject t=new JSONObject();t.put("type",type);t.put("value",value);t.put("method",method);t.put("date",new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date()));e.getJSONArray("transactions").put(t);save();employee(index);}catch(Exception ex){error(ex.getMessage());}}
    @Override protected void onActivityResult(int request,int result,Intent in){super.onActivityResult(request,result,in);if(result!=RESULT_OK||in==null)return;try{if(request==EXPORT){try(OutputStream o=getContentResolver().openOutputStream(in.getData())){o.write(data.toString(2).getBytes("UTF-8"));}}else if(request==IMPORT){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream s=getContentResolver().openInputStream(in.getData())){byte[] b=new byte[4096];int n;while((n=s.read(b))!=-1){out.write(b,0,n);if(out.size()>2_000_000)throw new Exception("Backup too large");}}JSONObject incoming=new JSONObject(out.toString("UTF-8"));JSONArray list=incoming.getJSONArray("employees");if(list.length()>8)throw new Exception("More than 8 employees");new AlertDialog.Builder(this).setTitle("Replace all local data?").setMessage("Import will overwrite current employees and transactions.").setNegativeButton("Cancel",null).setPositiveButton("Replace",(d,w)->{data=incoming;save();home();}).show();}}catch(Exception ex){error("Backup error: "+ex.getMessage());}}
}
